/**
 * Custom Cloudflare Pages build pipeline.
 *
 * Replaces `npx @cloudflare/next-on-pages` directly because that tool does not
 * propagate `export const runtime="edge"` from not-found.tsx into the Vercel
 * output function config in Next.js 15.5.2. We work around it by:
 *
 *   1. Create .vercel/project.json (same stub @cloudflare/next-on-pages uses)
 *   2. Run `npx vercel build`  (blog data is generated by npm run build inside)
 *   3. Patch _not-found.func/.vc-config.json → runtime=edge
 *   4. Run `npx @cloudflare/next-on-pages --skip-build`
 */
import fs from "fs";
import path from "path";
import { execSync } from "child_process";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.join(__dirname, "..");

function run(cmd) {
  console.log(`\n> ${cmd}`);
  execSync(cmd, { stdio: "inherit", cwd: root });
}

// ── Step 1: create .vercel/project.json stub ──────────────────────────────────
const vercelDir = path.join(root, ".vercel");
const projectJsonPath = path.join(vercelDir, "project.json");

if (!fs.existsSync(projectJsonPath)) {
  fs.mkdirSync(vercelDir, { recursive: true });
  fs.writeFileSync(
    projectJsonPath,
    JSON.stringify({ projectId: "_", orgId: "_", settings: { framework: "nextjs" } })
  );
  console.log("Created .vercel/project.json stub");
}

// ── Step 2: vercel build ──────────────────────────────────────────────────────
// PINNED, not @latest: vercel 54.20.0/54.20.1 (both released 2026-07-03) broke
// output mapping for prerendered routes ("Unable to find lambda for route:
// ..."), which failed every Cloudflare Pages deploy after the morning of
// 2026-07-03 while the repo was unchanged. 54.19.0 (2026-07-02) is the last
// release before the regression. Bump deliberately, never implicitly.
run("npx vercel@54.19.0 build");

// ── Step 3: patch _not-found.func/.vc-config.json ────────────────────────────
const functionsDir = path.join(root, ".vercel", "output", "functions");
const notFoundDir = path.join(functionsDir, "_not-found.func");
const notFoundConfig = path.join(notFoundDir, ".vc-config.json");

// Diagnostic: list all .func directories so the build log shows what was generated
if (fs.existsSync(functionsDir)) {
  const funcs = fs.readdirSync(functionsDir, { withFileTypes: true })
    .filter((e) => e.isDirectory() && e.name.endsWith(".func"))
    .map((e) => e.name);
  console.log(`patch: found ${funcs.length} .func directories:`, funcs.slice(0, 10).join(", ") + (funcs.length > 10 ? " ..." : ""));
} else {
  console.error("patch: ERROR — .vercel/output/functions/ does not exist. vercel build may have failed.");
  process.exit(1);
}

if (fs.existsSync(notFoundDir)) {
  const notFoundJsFiles = fs.readdirSync(notFoundDir).filter((f) => f.endsWith(".js"));
  console.log("patch: _not-found.func contents →", notFoundJsFiles);

  if (notFoundJsFiles.length === 0) {
    // Empty func directory — @cloudflare/next-on-pages can't bundle it.
    // Delete it so the tool falls back to the prerendered static version.
    fs.rmSync(notFoundDir, { recursive: true });
    console.log("patch: deleted empty _not-found.func/ — /_not-found will be served as static prerender");
  } else {
    const current = fs.existsSync(notFoundConfig)
      ? JSON.parse(fs.readFileSync(notFoundConfig, "utf8"))
      : null;

    console.log("patch: current .vc-config.json runtime →", current?.runtime);

    if (current?.runtime !== "edge") {
      let template = null;
      for (const entry of fs.readdirSync(functionsDir, { withFileTypes: true })) {
        if (!entry.isDirectory() || !entry.name.endsWith(".func") || entry.name === "_not-found.func") continue;
        const cfgPath = path.join(functionsDir, entry.name, ".vc-config.json");
        if (!fs.existsSync(cfgPath)) continue;
        const cfg = JSON.parse(fs.readFileSync(cfgPath, "utf8"));
        if (cfg.runtime === "edge") {
          template = cfg;
          console.log(`patch: using ${entry.name} as edge config template`);
          break;
        }
      }

      if (!template) {
        console.log("patch: no edge template found — using minimal edge config");
      }

      const entrypoint = notFoundJsFiles.find((f) => f === "index.js") ?? notFoundJsFiles[0];
      const patched = template ? { ...template, entrypoint } : { runtime: "edge", entrypoint };
      fs.writeFileSync(notFoundConfig, JSON.stringify(patched, null, 2));
      console.log(`patch: wrote runtime=edge, entrypoint=${entrypoint}`);
    } else {
      console.log("patch: already edge — no change needed");
    }
  }
} else {
  console.log("patch: _not-found.func/ not found — /_not-found is prerendered static");
}

// ── Step 4: @cloudflare/next-on-pages conversion ─────────────────────────────
// --experimental-minify: more aggressive dead-code elimination on the output
// Worker script. Added 2026-07-06 after a deploy hit Cloudflare's 3 MiB free-
// plan Worker size cap (next-on-pages bundles the whole site into one
// combined Worker, not per-route — this is the one safe, code-untouched
// lever available; if it isn't enough, the size growth is aggregate across
// many past features, not one new file, and needs either the CF Workers
// Paid plan (10 MiB cap) or real bundle-size investigation).
// --custom-entrypoint: TEMPORARY diagnostic wrapper (worker-entry.js) that
// captures console.error output on 5xx responses and ships it to Supabase
// Storage — the only way to read the world-route render error without
// Cloudflare log access. Remove with worker-entry.js once root-caused.
//
// --disableChunksDedup (2026-07-20): next-on-pages' chunk dedup emits
// "ReferenceError: async__chunk_N is not defined" — it replaces a webpack
// chunk code block with a bare identifier in a function file without
// prepending the matching import. Which function draws the missing binding
// reshuffles every build, 500ing one to three of the four Latent Space
// world routes on the HTML path (SSR require) while RSC/APIs stay fine.
// Disabling dedup keeps every chunk inlined per function: the bug class
// disappears. Cost: bigger worker — watch the 10 MiB (gzip) publish cap.
run("npx @cloudflare/next-on-pages --skip-build --experimental-minify --disableChunksDedup --custom-entrypoint ./worker-entry.js");
